/* Robux FAQ: Foundation tokens + page-specific composition. No height animation in observed source. */
.rbx-accordion {
  width: 100%;
  display: flex;
  flex-direction: column;
  gap: 12px;
}
.rbx-accordion-item {
  border: 1px solid var(--rbx-color-stroke-default);
  border-radius: 8px;
  overflow: hidden;
  padding: 8px 12px;
}
.rbx-accordion-header {
  margin: 0;
}
.rbx-accordion-trigger {
  width: 100%;
  min-height: 40px;
  padding: 0;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  border: 0;
  background: transparent;
  color: var(--rbx-color-content-default);
  font: var(--rbx-typography-title-medium-font);
  text-align: left;
  cursor: pointer;
}
.rbx-accordion-panel {
  color: var(--rbx-color-content-default);
  overflow: hidden;
  font: var(--rbx-typography-body-medium-font);
  white-space: pre-wrap;
  padding-bottom: 12px;
}
.rbx-accordion-chevron {
  display: inline-flex;
  flex-shrink: 0;
  color: var(--rbx-color-content-emphasis);
}
.rbx-accordion-chevron > :last-child {
  display: none;
}
.rbx-accordion-trigger[data-panel-open] .rbx-accordion-chevron > :first-child {
  display: none;
}
.rbx-accordion-trigger[data-panel-open] .rbx-accordion-chevron > :last-child {
  display: inline-block;
}
@media (min-width: 1141px) {
  .rbx-accordion {
    gap: 16px;
  }
}

"use client";

import type { ComponentProps } from "react";
import { Accordion as Primitive } from "@base-ui/react/accordion";
import { withClassName } from "../../lib/cx";
import { Icon } from "./icon";
import "./accordion.css";

// 동작과 접근성은 Base UI가 담당합니다. 이 파일은 스타일 연결만 담당합니다.
function AccordionRoot({
  multiple = true,
  className,
  ...props
}: ComponentProps<typeof Primitive.Root>) {
  return (
    <Primitive.Root
      {...props}
      multiple={multiple}
      className={withClassName("rbx-accordion", className)}
    />
  );
}

function AccordionItem({
  className,
  ...props
}: ComponentProps<typeof Primitive.Item>) {
  return (
    <Primitive.Item
      {...props}
      className={withClassName("rbx-accordion-item", className)}
    />
  );
}

function AccordionHeader({
  className,
  ...props
}: ComponentProps<typeof Primitive.Header>) {
  return (
    <Primitive.Header
      {...props}
      className={withClassName("rbx-accordion-header", className)}
    />
  );
}

function AccordionTrigger({
  className,
  ...props
}: ComponentProps<typeof Primitive.Trigger>) {
  return (
    <Primitive.Trigger
      {...props}
      className={withClassName("rbx-accordion-trigger", className)}
    />
  );
}

function AccordionPanel({
  className,
  ...props
}: ComponentProps<typeof Primitive.Panel>) {
  return (
    <Primitive.Panel
      {...props}
      className={withClassName("rbx-accordion-panel", className)}
    />
  );
}

/** 상태는 Base UI Trigger의 data-panel-open 속성을 따라갑니다. */
function AccordionChevron() {
  return (
    <span className="rbx-accordion-chevron" aria-hidden="true">
      <Icon name="icon-regular-chevron-large-down" size={20} />
      <Icon name="icon-regular-chevron-large-up" size={20} />
    </span>
  );
}
// Root/Portal 등 스타일 없는 파트와 제네릭 API는 원본을 그대로 보존합니다.
export const Accordion = {
  ...Primitive,
  Chevron: AccordionChevron,
  Root: AccordionRoot,
  Item: AccordionItem,
  Header: AccordionHeader,
  Trigger: AccordionTrigger,
  Panel: AccordionPanel,
};

import type { ComponentProps, CSSProperties } from "react";
import { cx } from "../../lib/cx";
import "./icon.css";
/** ReactChat / Navigation 배포 CSS에서 확인한 glyph. 그림은 CSS mask, 색은 currentColor입니다. */
export type IconName =
  | "icon-regular-house"
  | "icon-regular-person"
  | "icon-regular-speech-bubble-align-center"
  | "icon-regular-two-people"
  | "icon-regular-person-standing"
  | "icon-regular-backpack"
  | "icon-regular-hand-two-arrows-horizontal"
  | "icon-regular-three-people"
  | "icon-regular-fountain-pen-nib"
  | "icon-regular-building-store"
  | "icon-regular-gift-card"
  | "icon-regular-chevron-large-up"
  | "icon-filled-arrow-spin-clockwise"
  | "icon-filled-calendar"
  | "icon-filled-check"
  | "icon-regular-chevron-large-down"
  | "icon-regular-chevron-large-left"
  | "icon-regular-chevron-large-right"
  | "icon-regular-circle-i"
  | "icon-filled-circle-i"
  | "icon-filled-clock"
  | "icon-regular-gear"
  | "icon-filled-globe-simplified"
  | "icon-filled-magnifying-glass"
  | "icon-regular-person-plus"
  | "icon-regular-plus-large"
  | "icon-filled-premium"
  | "icon-regular-roblox-plus"
  | "icon-filled-smartphone-portrait"
  | "icon-filled-speech-bubble-round"
  | "icon-regular-squares-grid-qr"
  | "icon-filled-three-dots-horizontal"
  | "icon-filled-tilt"
  | "icon-regular-triangle-exclamation"
  | "icon-filled-two-people"
  | "icon-filled-verified-backplate"
  | "icon-filled-verified-check"
  | "icon-regular-x";
export type IconProps = Omit<ComponentProps<"span">, "children"> & {
  name: IconName;
  size?: number;
};
export function Icon({
  name,
  size = 20,
  style,
  className,
  ...props
}: IconProps) {
  return (
    <span
      aria-hidden="true"
      {...props}
      data-icon={name}
      className={cx("rbx-icon", className)}
      style={{ "--rbx-icon-size": `${size}px`, ...style } as CSSProperties}
    />
  );
}

/** Base UI는 className에 문자열 또는 상태 함수를 받습니다. 둘 다 보존합니다. */
export function withClassName<State>(
  base: string,
  custom?: string | ((state: State) => string | undefined),
) {
  return (state: State) =>
    [base, typeof custom === "function" ? custom(state) : custom]
      .filter(Boolean)
      .join(" ");
}
export function cx(...classes: (string | undefined | false)[]) {
  return classes.filter(Boolean).join(" ");
}

