import type { ComponentProps } from "react";
import { cx } from "../../lib/cx";
import "./alert.css";

export function Alert({ className, ...props }: ComponentProps<"div">) {
  return (
    <div role="status" {...props} className={cx("rbx-alert", className)} />
  );
}

export function AlertTitle({ className, ...props }: ComponentProps<"h3">) {
  return <h3 {...props} className={cx("rbx-card-title", className)} />;
}

export function AlertDescription({ className, ...props }: ComponentProps<"p">) {
  return <p {...props} className={cx("rbx-description", className)} />;
}

/** Base UI는 className에 문자열 또는 상태 함수를 받습니다. 둘 다 보존합니다. */
export function withClassName<State>(
  base: string,
  custom?: string | ((state: State) => string | undefined),
) {
  return (state: State) =>
    [base, typeof custom === "function" ? custom(state) : custom]
      .filter(Boolean)
      .join(" ");
}
export function cx(...classes: (string | undefined | false)[]) {
  return classes.filter(Boolean).join(" ");
}

