/* breadcrumb — semantic HTML composition. */
.rbx-breadcrumb-list {
  list-style: none;
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
  padding: 0;
}
.rbx-breadcrumb-item + .rbx-breadcrumb-item::before {
  content: "/";
  color: var(--rbx-color-content-muted);
  margin-right: 8px;
}

import type { ComponentProps } from "react";
import { cx } from "../../lib/cx";
import "./breadcrumb.css";

export function Breadcrumb({ className, ...props }: ComponentProps<"nav">) {
  return (
    <nav
      aria-label="Breadcrumb"
      {...props}
      className={cx("rbx-breadcrumb", className)}
    />
  );
}

export function BreadcrumbList({ className, ...props }: ComponentProps<"ol">) {
  return <ol {...props} className={cx("rbx-breadcrumb-list", className)} />;
}

export function BreadcrumbItem({ className, ...props }: ComponentProps<"li">) {
  return <li {...props} className={cx("rbx-breadcrumb-item", className)} />;
}

export function BreadcrumbLink({ className, ...props }: ComponentProps<"a">) {
  return <a {...props} className={cx("rbx-nav-link", className)} />;
}

/** Base UI는 className에 문자열 또는 상태 함수를 받습니다. 둘 다 보존합니다. */
export function withClassName<State>(
  base: string,
  custom?: string | ((state: State) => string | undefined),
) {
  return (state: State) =>
    [base, typeof custom === "function" ? custom(state) : custom]
      .filter(Boolean)
      .join(" ");
}
export function cx(...classes: (string | undefined | false)[]) {
  return classes.filter(Boolean).join(" ");
}

