  --rbx-fui-future-alpha-color-system-progress: var(
    --rbx-dark-mode-system-contrast
  );
}

/* 표면과 내용 간격을 분리합니다. 이미지와 문서 예제 프레임에는 여백을 강제하지 않습니다. */
.rbx-card {
  --rbx-card-inset: 16px;
  position: relative;
  min-width: 0;
  border: 1px solid var(--rbx-color-stroke-default);
  border-radius: 8px;
  background: var(--rbx-color-surface-0);
  color: var(--rbx-color-content-emphasis);
  overflow: hidden;
}
.rbx-card[data-density="compact"] {
  --rbx-card-inset: 12px;
}
.rbx-card[data-variant="filled"] {
  border-color: transparent;
  background: var(--rbx-color-shift-200);
}
.rbx-card[data-variant="plain"] {
  border: 0;
  background: transparent;
  overflow: visible;
}
.rbx-card[data-selected] {
  box-shadow: inset 0 0 0 2px var(--rbx-color-system-emphasis);
}
.rbx-card[data-variant="plain"][data-selected] {
  box-shadow: none;
}
.rbx-card[data-variant="plain"][data-selected] > .rbx-card-media::after {
  content: "";
  position: absolute;
  inset: 0;
  border: 2px solid var(--rbx-color-system-emphasis);
  border-radius: inherit;
  pointer-events: none;
}
.rbx-card-header,
.rbx-card-content,
.rbx-card-footer {
  padding: var(--rbx-card-inset);
  min-width: 0;
}
.rbx-card-header {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 4px;
}
.rbx-card-content {
  display: grid;
  gap: 12px;
  font: var(--rbx-typography-body-medium-font);
}
.rbx-card-header + .rbx-card-content {
  padding-top: 0;
}
.rbx-card-title {
  margin: 0;
  font: var(--rbx-typography-title-large-font);
  overflow-wrap: anywhere;
}
.rbx-card-description {
  margin: 0;
  color: var(--rbx-color-content-default);
  font: var(--rbx-typography-body-medium-font);
  overflow-wrap: anywhere;
}
.rbx-card-meta {
  margin: 0;
  color: var(--rbx-color-content-default);
  font: var(--rbx-typography-body-small-font);
  overflow-wrap: anywhere;
}
.rbx-card-footer {
  position: relative;
  z-index: 1;
  display: flex;
  align-items: center;
  justify-content: flex-end;
  flex-wrap: wrap;
  gap: 8px;
  padding-top: 0;
}
.rbx-card-footer[data-divider] {
  padding-top: 12px;
  border-top: 1px solid var(--rbx-color-stroke-default);
}
.rbx-card-media {
  position: relative;
  aspect-ratio: 16 / 9;
  overflow: hidden;
  background: var(--rbx-color-shift-200);
}
.rbx-card-media[data-ratio="square"] {
  aspect-ratio: 1;
}
.rbx-card-media[data-ratio="wide"] {
  aspect-ratio: 21 / 9;
}
.rbx-card-image {
  display: block;
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
}
.rbx-card-image[data-fit="contain"] {
  object-fit: contain;
  padding: 12px;
}
.rbx-card-image-fallback {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  padding: 16px;
  color: var(--rbx-color-content-default);
  font: var(--rbx-typography-body-small-font);
}
.rbx-card[data-variant="plain"] > .rbx-card-media {
  border-radius: 8px;
}
.rbx-card[data-variant="plain"]
  > :is(.rbx-card-header, .rbx-card-content, .rbx-card-footer) {
  padding-inline: 0;
}
.rbx-card[data-variant="plain"] > .rbx-card-header {
  padding-top: 8px;
  padding-bottom: 0;
}
.rbx-card[data-variant="plain"] > .rbx-card-header + .rbx-card-footer {
  padding-top: 12px;
}
.rbx-card[data-layout="horizontal"] {
  display: grid;
  grid-template-columns: minmax(80px, 30%) minmax(0, 1fr);
  align-items: stretch;
}
.rbx-card[data-layout="horizontal"] > .rbx-card-media {
  aspect-ratio: 1;
  min-height: 100%;
}
.rbx-card[data-layout="horizontal"] > .rbx-card-content {
  align-content: center;
  gap: 4px;
}
.rbx-card[data-layout="horizontal"][data-variant="plain"] {
  gap: 12px;
}
.rbx-card-link,
.rbx-card-action {
  color: inherit;
  text-decoration: none;
  outline: none;
}
.rbx-card-action {
  padding: 0;
  border: 0;
  background: transparent;
  font: inherit;
  text-align: inherit;
  cursor: pointer;
}
:is(.rbx-card-link, .rbx-card-action)[data-stretch]::after {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 1;
  border-radius: 8px;
}
:is(.rbx-card-link, .rbx-card-action)[data-stretch]:focus-visible::after {
  outline: 2px solid var(--rbx-color-system-emphasis);
  outline-offset: -2px;
}
:is(.rbx-card-link, .rbx-card-action):not([data-stretch]):focus-visible {
  outline: 2px solid var(--rbx-color-system-emphasis);
  outline-offset: 3px;
}
.rbx-card:has(:is(.rbx-card-link, .rbx-card-action:enabled):hover)
  .rbx-card-title {
  text-decoration: underline;
  text-underline-offset: 3px;
}
@media (prefers-reduced-motion: no-preference) {
  .rbx-card-image {
    transition: transform 160ms ease-out;
  }
  .rbx-card:has(:is(.rbx-card-link, .rbx-card-action:enabled):hover)
    .rbx-card-image[data-fit="cover"] {
    transform: scale(1.02);
  }
}

"use client";
import { useState, type ComponentProps, type ReactNode } from "react";
import { cx } from "../../lib/cx";
import "./card.css";

export type CardProps = ComponentProps<"section"> & {
  /** 카드의 표면입니다. @defaultValue "outlined" */
  variant?: "outlined" | "filled" | "plain";
  /** 본문과 가장자리 사이의 간격입니다. @defaultValue "default" */
  density?: "default" | "compact";
  /** horizontal은 Media와 Content를 좌우로 배치합니다. @defaultValue "vertical" */
  layout?: "vertical" | "horizontal";
  /** 선택 상태를 표면에 표시합니다. 버튼에도 aria-pressed 등을 지정합니다. @defaultValue false */
  selected?: boolean;
};
export function Card({
  variant = "outlined",
  density = "default",
  layout = "vertical",
  selected = false,
  className,
  ...props
}: CardProps) {
  return (
    <section
      {...props}
      data-variant={variant}
      data-density={density}
      data-layout={layout}
      data-selected={selected || undefined}
      className={cx("rbx-card", className)}
    />
  );
}

export function CardHeader({ className, ...props }: ComponentProps<"header">) {
  return <header {...props} className={cx("rbx-card-header", className)} />;
}
export type CardTitleProps = ComponentProps<"h3"> & {
  /** 페이지의 제목 계층에 맞게 선택합니다. @defaultValue "h3" */
  as?: "h2" | "h3" | "h4";
};
export function CardTitle({
  as: Tag = "h3",
  className,
  ...props
}: CardTitleProps) {
  return <Tag {...props} className={cx("rbx-card-title", className)} />;
}
export function CardDescription({ className, ...props }: ComponentProps<"p">) {
  return <p {...props} className={cx("rbx-card-description", className)} />;
}
export function CardMeta({ className, ...props }: ComponentProps<"p">) {
  return <p {...props} className={cx("rbx-card-meta", className)} />;
}
export function CardContent({ className, ...props }: ComponentProps<"div">) {
  return <div {...props} className={cx("rbx-card-content", className)} />;
}
export type CardFooterProps = ComponentProps<"div"> & {
  /** 본문과 작업 영역 사이에 구분선을 표시합니다. @defaultValue false */
  divider?: boolean;
};
export function CardFooter({
  divider = false,
  className,
  ...props
}: CardFooterProps) {
  return (
    <div
      {...props}
      data-divider={divider || undefined}
      className={cx("rbx-card-footer", className)}
    />
  );
}
export type CardMediaProps = ComponentProps<"div"> & {
  /** 썸네일 비율입니다. 가로 배치에서는 정사각형을 기준으로 늘어납니다. @defaultValue "video" */
  ratio?: "video" | "square" | "wide";
};
export function CardMedia({
  ratio = "video",
  className,
  ...props
}: CardMediaProps) {
  return (
    <div
      {...props}
      data-ratio={ratio}
      className={cx("rbx-card-media", className)}
    />
  );
}
export type CardImageProps = Omit<ComponentProps<"img">, "alt"> & {
  /** 제목과 중복되는 장식 이미지에는 빈 문자열을 지정합니다. */
  alt: string;
  /** 이미지가 없거나 로딩에 실패했을 때 표시할 내용입니다. */
  fallback?: ReactNode;
  /** cover는 채우기, contain은 이미지 전체 표시입니다. @defaultValue "cover" */
  fit?: "cover" | "contain";
};
export function CardImage({
  src,
  srcSet,
  alt,
  fallback = "미리보기 없음",
  fit = "cover",
  className,
  onError,
  ...props
}: CardImageProps) {
  const [failed, setFailed] = useState<string>();
  // src 또는 srcSet이 바뀌면 이전 실패 결과를 재사용하지 않습니다.
  const identity = JSON.stringify([src, srcSet]);
  if ((!src && !srcSet) || failed === identity) {
    return (
      <div
        className={cx("rbx-card-image-fallback", className)}
        role={alt ? "img" : undefined}
        aria-label={alt || undefined}
        aria-hidden={alt ? undefined : true}
      >
        {fallback}
      </div>
    );
  }
  return (
    <img
      loading="lazy"
      decoding="async"
      {...props}
      src={src}
      srcSet={srcSet}
      alt={alt}
      data-fit={fit}
      className={cx("rbx-card-image", className)}
      onError={(event) => {
        setFailed(identity);
        onError?.(event);
      }}
    />
  );
}
export type CardLinkProps = ComponentProps<"a"> & {
  /** 제목 링크의 클릭 영역을 카드 전체로 넓힙니다. @defaultValue true */
  stretch?: boolean;
};
// Card 전체를 링크로 감싸지 않아 Footer에 별도 버튼을 둘 수 있습니다.
export function CardLink({
  stretch = true,
  className,
  ...props
}: CardLinkProps) {
  return (
    <a
      {...props}
      data-stretch={stretch || undefined}
      className={cx("rbx-card-link", className)}
    />
  );
}

export type CardActionProps = ComponentProps<"button"> & {
  /** 제목 버튼의 클릭 영역을 카드 전체로 넓힙니다. @defaultValue true */
  stretch?: boolean;
};
export function CardAction({
  stretch = true,
  type = "button",
  className,
  ...props
}: CardActionProps) {
  return (
    <button
      {...props}
      type={type}
      data-stretch={stretch || undefined}
      className={cx("rbx-card-action", className)}
    />
  );
}

/** Base UI는 className에 문자열 또는 상태 함수를 받습니다. 둘 다 보존합니다. */
export function withClassName<State>(
  base: string,
  custom?: string | ((state: State) => string | undefined),
) {
  return (state: State) =>
    [base, typeof custom === "function" ? custom(state) : custom]
      .filter(Boolean)
      .join(" ");
}
export function cx(...classes: (string | undefined | false)[]) {
  return classes.filter(Boolean).join(" ");
}

