  scrollbar-width: none;
  scroll-snap-type: x proximity;
}
.rbx-carousel-content {
  display: flex;
  gap: 12px;
  width: max-content;
}
.rbx-carousel-item {
  display: flex;
  flex-direction: column;
  flex-shrink: 0;
  gap: 8px;
  width: 280px;
  padding: 0;
  border: 0;
