}
.rbx-carousel-controls {
  display: flex;
  justify-content: flex-end;
  gap: 8px;
  margin-top: 8px;
}

"use client";
import { useEffect, useRef, useState, type ReactNode } from "react";
import { ScrollArea } from "@base-ui/react/scroll-area";
import { Button } from "@base-ui/react/button";
import { IconButton } from "./icon-button";
import { cx } from "../../lib/cx";
import "./carousel.css";
export type CollectionItem = {
  id: string;
  title: string;
  description?: string;
  media: ReactNode;
};
/** Base UI ScrollArea + Button 조합. 카드의 280/160/12px 규칙은 Account Status에서 측정했습니다. */
export function Carousel({
  label,
  items,
  onItemClick,
  className,
}: {
  label: string;
  items: CollectionItem[];
  onItemClick?: (id: string) => void;
  className?: string;
}) {
  const viewport = useRef<HTMLDivElement>(null);
  const content = useRef<HTMLDivElement>(null);
  const [edges, setEdges] = useState({ start: true, end: true });
  function updateEdges() {
    const el = viewport.current;
    if (el)
      setEdges({
        start: Math.abs(el.scrollLeft) < 1,
        end: Math.abs(el.scrollLeft) + el.clientWidth >= el.scrollWidth - 1,
      });
  }
  useEffect(() => {
    const observer = new ResizeObserver(updateEdges);
    if (viewport.current) observer.observe(viewport.current);
    if (content.current) observer.observe(content.current);
    updateEdges();
    return () => observer.disconnect();
  }, [items.length]);
  function scroll(direction: number) {
    const el = viewport.current;
    if (!el) return;
    const rtl = getComputedStyle(el).direction === "rtl";
    el.scrollBy({
      left: direction * (rtl ? -292 : 292),
      behavior: matchMedia("(prefers-reduced-motion: reduce)").matches
        ? "instant"
        : "smooth",
    });
  }
  return (
    <section
      className={cx("rbx-carousel", className)}
      aria-label={label}
      aria-roledescription="carousel"
    >
      <ScrollArea.Root>
        <ScrollArea.Viewport
          className="rbx-carousel-viewport"
          ref={viewport}
          onScroll={updateEdges}
        >
          <ScrollArea.Content className="rbx-carousel-content" ref={content}>
            {items.map((item) => (
              <Button
                key={item.id}
                className="rbx-carousel-item"
                onClick={() => onItemClick?.(item.id)}
              >
                <span className="rbx-carousel-media">{item.media}</span>
                <span className="rbx-carousel-copy">
                  <span className="rbx-carousel-title">{item.title}</span>
                  {item.description && (
                    <span className="rbx-carousel-description">
                      {item.description}
                    </span>
                  )}
                </span>
              </Button>
            ))}
          </ScrollArea.Content>
        </ScrollArea.Viewport>
      </ScrollArea.Root>
      <div className="rbx-carousel-controls">
        <IconButton
          icon="icon-regular-chevron-large-left"
          aria-label="Previous cards"
          size="sm"
          variant="utility"
          circular
          disabled={edges.start}
          onClick={() => scroll(-1)}
        />
        <IconButton
          icon="icon-regular-chevron-large-right"
          aria-label="Next cards"
          size="sm"
          variant="utility"
          circular
          disabled={edges.end}
          onClick={() => scroll(1)}
        />
      </div>
    </section>
  );
}

.rbx-icon-button {
  width: 48px;
  height: 48px;
  min-height: 48px;
  padding: 0;
  border: 0;
  background-color: var(--rbx-color-action-emphasis-background);
  color: var(--rbx-color-action-emphasis-foreground);
}
.rbx-icon-button[data-size="md"] {
  width: 40px;
  height: 40px;
  min-height: 40px;
}
.rbx-icon-button[data-size="sm"] {
  width: 32px;
  height: 32px;
  min-height: 32px;
}
.rbx-icon-button[data-size="xs"] {
  width: 24px;
  height: 24px;
  min-height: 24px;
  border-radius: 4px;
}
.rbx-icon-button[data-circular] {
  border-radius: 9999px;
}
.rbx-icon-button[data-variant="standard"] {
  background-color: var(--rbx-color-action-standard-background);
  color: var(--rbx-color-action-standard-foreground);
}
.rbx-icon-button[data-variant="alert"] {
  background-color: var(--rbx-color-action-alert-background);
  color: var(--rbx-color-action-alert-foreground);
}
.rbx-icon-button[data-variant="utility"] {
  background-color: var(--rbx-color-action-link-background);
  color: var(--rbx-color-content-emphasis);
}
.rbx-icon-button[data-variant="utility"][data-selected] {
  background-color: var(--rbx-color-shift-300);
}
.rbx-icon-button[data-variant="over-media"] {
  background-color: var(--rbx-color-over-media-0);
  color: var(--rbx-color-content-emphasis);
}
.rbx-icon-button:is(:disabled, [data-disabled]):is(
    [data-variant="emphasis"],
    [data-variant="alert"]
  ) {
  background-color: var(--rbx-color-action-standard-background);
  color: var(--rbx-color-action-standard-foreground);
}

"use client";
import type { ComponentProps } from "react";
import { Button as Primitive } from "@base-ui/react/button";
import { withClassName } from "../../lib/cx";
import { Icon, type IconName } from "./icon";
import "./icon-button.css";
export type IconButtonProps = Omit<
  ComponentProps<typeof Primitive>,
  "children"
> & {
  /** 스크린 리더가 읽을 작업 이름입니다. */
  "aria-label": string;
  /** 표시할 아이콘 이름입니다. */
  icon: IconName;
  /** 버튼 높이와 아이콘 크기입니다. @defaultValue "lg" */
  size?: "xs" | "sm" | "md" | "lg";
  /** 버튼의 색상과 강조 수준입니다. @defaultValue "emphasis" */
  variant?: "emphasis" | "standard" | "alert" | "utility" | "over-media";
  /** 원형으로 표시합니다. @defaultValue false */
  circular?: boolean;
  /** 선택한 상태의 스타일을 적용합니다. @defaultValue false */
  selected?: boolean;
};
/** 아이콘 전용 버튼은 텍스트 Button과 glyph 크기/utility 배경 규칙이 다릅니다. */
export function IconButton({
  icon,
  size = "lg",
  variant = "emphasis",
  circular = false,
  selected = false,
  className,
  ...props
}: IconButtonProps) {
  return (
    <Primitive
      {...props}
      data-size={size}
      data-variant={variant}
      data-circular={circular || undefined}
      data-selected={selected || undefined}
      className={withClassName("rbx-icon-button", className)}
    >
      <Icon name={icon} size={{ xs: 16, sm: 20, md: 24, lg: 28 }[size]} />
    </Primitive>
  );
}

