    var(--rbx-color-state-press),
    var(--rbx-color-state-press)
  );
}
.rbx-icon-button {
  width: 40px;
  padding: 0;
  flex-shrink: 0;
}
.rbx-label {
  color: var(--rbx-color-content-emphasis);
  font-weight: 600;
}
.rbx-description {
  color: var(--rbx-color-content-default);
  font-size: 0.875rem;
  line-height: 1.5;
  margin: 4px 0 0;
}
.rbx-error {
  color: var(--rbx-color-system-alert);
  font-size: 0.875rem;
