Source: https://css.rbxcdn.com/835ad8483ecae12366bf4b80701ee78af7c5b58cdb95a529e061851cf7bc1c7f-Builder.css
Font binaries are loaded from Roblox CDN; not bundled. */
@font-face {
  font-family: Builder Sans;
