"use client";
import type { ComponentProps, ReactNode } from "react";
import { Input as Primitive } from "@base-ui/react/input";
import { withClassName } from "../../lib/cx";
import "./input.css";

export type InputProps = ComponentProps<typeof Primitive> & {
  /** native size(글자 수)와 달리 컨트롤 높이를 정합니다. @defaultValue "lg" */
  controlSize?: "xs" | "sm" | "md" | "lg";
  /** 입력 영역의 배경과 테두리 표현입니다. @defaultValue "standard" */
  variant?: "standard" | "contrast" | "utility";
  /** 입력 영역 앞에 표시할 아이콘이나 내용입니다. */
  leading?: ReactNode;
  /** 입력 영역 뒤에 표시할 아이콘이나 내용입니다. */
  trailing?: ReactNode;
};
/** Base UI는 입력/Field 연동, 외부 래퍼는 아이콘과 테두리만 담당합니다. ref는 input에 전달됩니다. */
export function Input({
  controlSize = "lg",
  variant = "standard",
  leading,
  trailing,
  className,
  ...props
}: InputProps) {
  const input = (
    <Primitive
      {...props}
      data-size={controlSize}
      data-variant={variant}
      className={withClassName("rbx-input", className)}
    />
  );
  if (!leading && !trailing) return input;
  return (
    <div
      className="rbx-input-group"
      data-size={controlSize}
      data-variant={variant}
      data-disabled={props.disabled || undefined}
      data-invalid={props["aria-invalid"] === true || undefined}
    >
      {leading && <span className="rbx-input-adornment">{leading}</span>}
      {input}
      {trailing && <span className="rbx-input-adornment">{trailing}</span>}
    </div>
  );
}

/** Base UI는 className에 문자열 또는 상태 함수를 받습니다. 둘 다 보존합니다. */
export function withClassName<State>(
  base: string,
  custom?: string | ((state: State) => string | undefined),
) {
  return (state: State) =>
    [base, typeof custom === "function" ? custom(state) : custom]
      .filter(Boolean)
      .join(" ");
}
export function cx(...classes: (string | undefined | false)[]) {
  return classes.filter(Boolean).join(" ");
}

