/* Security list: outer 12px horizontal inset, inner 16px vertical inset, 12px gaps. */
.rbx-list {
  list-style: none;
  margin: 0;
  padding: 0;
  width: 100%;
}
.rbx-list-item {
  border-bottom: 1px solid var(--rbx-color-stroke-default);
}
.rbx-list-action {
  display: block;
  width: 100%;
  background: transparent;
  color: inherit;
  border: 0;
  padding: 0;
  text-align: left;
  cursor: pointer;
}
.rbx-list-action:hover {
  background: var(--rbx-color-state-hover);
}
.rbx-list-action:active {
  background: var(--rbx-color-state-press);
}
.rbx-list-content {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 16px 12px;
}
.rbx-list-body {
  flex: 1;
  min-width: 0;
}
.rbx-list-leading,
.rbx-list-trailing {
  display: inline-flex;
