@import "./progress.css";
/* Meter: 공통 구조는 theme.css, 컴포넌트 전용 조정은 아래에 작성합니다. */
.rbx-meter {
  display: grid;
  gap: 8px;
  width: 100%;
}

"use client";

import type { ComponentProps } from "react";
import { Meter as Primitive } from "@base-ui/react/meter";
import { withClassName } from "../../lib/cx";
import "./meter.css";

// 동작과 접근성은 Base UI가 담당합니다. 이 파일은 스타일 연결만 담당합니다.
function MeterRoot({
  className,
  ...props
}: ComponentProps<typeof Primitive.Root>) {
  return (
    <Primitive.Root
      {...props}
      className={withClassName("rbx-meter", className)}
    />
  );
}

function MeterLabel({
  className,
  ...props
}: ComponentProps<typeof Primitive.Label>) {
  return (
    <Primitive.Label
      {...props}
      className={withClassName("rbx-label", className)}
    />
  );
}

function MeterValue({
  className,
  ...props
}: ComponentProps<typeof Primitive.Value>) {
  return (
    <Primitive.Value
      {...props}
      className={withClassName("rbx-description", className)}
    />
  );
}

function MeterTrack({
  className,
  ...props
}: ComponentProps<typeof Primitive.Track>) {
  return (
    <Primitive.Track
      {...props}
      className={withClassName("rbx-progress-track", className)}
    />
  );
}

function MeterIndicator({
  className,
  ...props
}: ComponentProps<typeof Primitive.Indicator>) {
  return (
    <Primitive.Indicator
      {...props}
      className={withClassName("rbx-progress-indicator", className)}
    />
  );
}

// Root/Portal 등 스타일 없는 파트와 제네릭 API는 원본을 그대로 보존합니다.
export const Meter = {
  ...Primitive,
  Root: MeterRoot,
  Label: MeterLabel,
  Value: MeterValue,
  Track: MeterTrack,
  Indicator: MeterIndicator,
};

/* Progress: 공통 구조는 theme.css, 컴포넌트 전용 조정은 아래에 작성합니다. */
.rbx-progress {
  display: grid;
  gap: 8px;
  width: 100%;
}
.rbx-progress-track {
  height: 6px;
  width: 100%;
  overflow: hidden;
  border-radius: 99px;
  background: var(--rbx-color-shift-300);
}
.rbx-progress-indicator {
  height: 100%;
  background: var(--rbx-color-system-emphasis);
  border-radius: inherit;
  transition: width 0.2s;
}
.rbx-progress-indicator[data-indeterminate] {
  width: 35%;
  animation: rbx-progress 1.3s infinite ease-in-out;
}
@keyframes rbx-progress {
  from {
    transform: translateX(-100%);
  }
  to {
    transform: translateX(350%);
  }
}

/** Base UI는 className에 문자열 또는 상태 함수를 받습니다. 둘 다 보존합니다. */
export function withClassName<State>(
  base: string,
  custom?: string | ((state: State) => string | undefined),
) {
  return (state: State) =>
    [base, typeof custom === "function" ? custom(state) : custom]
      .filter(Boolean)
      .join(" ");
}
export function cx(...classes: (string | undefined | false)[]) {
  return classes.filter(Boolean).join(" ");
}

