/* Community educational tooltip variant. Standard popovers retain the shared surface. */
.rbx-popup[data-variant="inverse"] {
  padding: 12px;
  border: 0;
  border-radius: 8px;
  background: var(--rbx-inverse-surface-0);
  color: var(--rbx-inverse-content-emphasis);
