.rbx-scroll-area {
  position: relative;
  overflow: hidden;
}
.rbx-scroll-viewport {
  width: 100%;
  height: 100%;
}
.rbx-scrollbar {
  display: flex;
  width: 6px;
  padding: 1px;
  margin: 4px;
  opacity: 0;
  transition: opacity 0.15s;
}
.rbx-scrollbar[data-hovering],
.rbx-scrollbar[data-scrolling] {
