/* Browser preferences: transparent input shell, 1px contrast-alpha stroke. */
.rbx-select-trigger {
  justify-content: space-between;
  width: 100%;
  height: 48px;
  min-height: 48px;
  padding: 1px 16px;
  border: 1px solid var(--rbx-color-stroke-contrast-alpha);
  background: transparent;
  color: var(--rbx-color-content-default);
  font: var(--rbx-typography-body-large-font);
}
.rbx-select-trigger[data-size="md"] {
  height: 40px;
  min-height: 40px;
  padding-inline: 12px;
  font: var(--rbx-typography-body-medium-font);
}
.rbx-select-trigger[data-size="sm"] {
  height: 32px;
  min-height: 32px;
  padding-inline: 12px;
  font: var(--rbx-typography-body-small-font);
}
.rbx-select-trigger[data-size="xs"] {
  height: 24px;
  min-height: 24px;
  padding-inline: 8px;
  border-radius: 4px;
  font: var(--rbx-typography-body-small-font);
}
.rbx-select-trigger:focus-visible {
  outline: none;
  border-color: var(--rbx-color-system-emphasis);
  box-shadow: inset 0 0 0 1px var(--rbx-color-system-emphasis);
}
.rbx-scroll-arrow {
  padding: 4px;
  text-align: center;
  background: var(--rbx-color-surface-100);
}

"use client";

import type { ComponentProps } from "react";
import { Select as Primitive } from "@base-ui/react/select";
import { withClassName } from "../../lib/cx";
import "./select.css";

// 동작과 접근성은 Base UI가 담당합니다. 이 파일은 스타일 연결만 담당합니다.
export type SelectTriggerProps = ComponentProps<typeof Primitive.Trigger> & {
  /** 여는 버튼 높이입니다. @defaultValue "lg" */
  size?: "xs" | "sm" | "md" | "lg";
};
function SelectTrigger({
  size = "lg",
  className,
  ...props
}: SelectTriggerProps) {
  return (
    <Primitive.Trigger
      {...props}
      data-size={size}
      className={withClassName("rbx-select-trigger", className)}
    />
  );
}

export type SelectPopupProps = ComponentProps<typeof Primitive.Popup> & {
  /** 목록 항목의 글자 크기와 여백입니다. @defaultValue "lg" */
  size?: "xs" | "sm" | "md" | "lg";
};
function SelectPopup({ size = "lg", className, ...props }: SelectPopupProps) {
  return (
    <Primitive.Popup
      {...props}
      data-size={size}
      className={withClassName("rbx-popup", className)}
    />
  );
}

function SelectPositioner({
  alignItemWithTrigger = false,
  sideOffset = 8,
  className,
  ...props
}: ComponentProps<typeof Primitive.Positioner>) {
  return (
    <Primitive.Positioner
      {...props}
      alignItemWithTrigger={alignItemWithTrigger}
      sideOffset={sideOffset}
      className={withClassName("rbx-positioner", className)}
    />
  );
}

function SelectItem({
  className,
  ...props
}: ComponentProps<typeof Primitive.Item>) {
  return (
    <Primitive.Item
      {...props}
      className={withClassName("rbx-option", className)}
    />
  );
}

function SelectItemIndicator({
  className,
  ...props
}: ComponentProps<typeof Primitive.ItemIndicator>) {
  return (
    <Primitive.ItemIndicator
      {...props}
      className={withClassName("rbx-option-indicator", className)}
    />
  );
}

function SelectGroupLabel({
  className,
  ...props
}: ComponentProps<typeof Primitive.GroupLabel>) {
  return (
    <Primitive.GroupLabel
      {...props}
      className={withClassName("rbx-group-label", className)}
    />
  );
}

function SelectScrollUpArrow({
  className,
  ...props
}: ComponentProps<typeof Primitive.ScrollUpArrow>) {
  return (
    <Primitive.ScrollUpArrow
      {...props}
      className={withClassName("rbx-scroll-arrow", className)}
    />
  );
}

function SelectScrollDownArrow({
  className,
  ...props
}: ComponentProps<typeof Primitive.ScrollDownArrow>) {
  return (
    <Primitive.ScrollDownArrow
      {...props}
      className={withClassName("rbx-scroll-arrow", className)}
    />
  );
}

function SelectSeparator({
  className,
  ...props
}: ComponentProps<typeof Primitive.Separator>) {
  return (
    <Primitive.Separator
      {...props}
      className={withClassName("rbx-separator", className)}
    />
  );
}

// Root/Portal 등 스타일 없는 파트와 제네릭 API는 원본을 그대로 보존합니다.
export const Select = {
  ...Primitive,
  Trigger: SelectTrigger,
  Popup: SelectPopup,
  Positioner: SelectPositioner,
  Item: SelectItem,
  ItemIndicator: SelectItemIndicator,
  GroupLabel: SelectGroupLabel,
  ScrollUpArrow: SelectScrollUpArrow,
  ScrollDownArrow: SelectScrollDownArrow,
  Separator: SelectSeparator,
};

/** Base UI는 className에 문자열 또는 상태 함수를 받습니다. 둘 다 보존합니다. */
export function withClassName<State>(
  base: string,
  custom?: string | ((state: State) => string | undefined),
) {
  return (state: State) =>
    [base, typeof custom === "function" ? custom(state) : custom]
      .filter(Boolean)
      .join(" ");
}
export function cx(...classes: (string | undefined | false)[]) {
  return classes.filter(Boolean).join(" ");
}

