  border-radius: 8px;
  background: var(--rbx-color-common-shimmer);
  min-height: 16px;
  animation: rbx-pulse 1.5s ease-in-out infinite alternate;
}
@keyframes rbx-pulse {
  to {
    opacity: 0.45;
  }
}

import type { ComponentProps } from "react";
import { cx } from "../../lib/cx";
import "./skeleton.css";

export function Skeleton({ className, ...props }: ComponentProps<"div">) {
  return (
    <div
      aria-hidden="true"
      {...props}
      className={cx("rbx-skeleton", className)}
    />
  );
}

/** Base UI는 className에 문자열 또는 상태 함수를 받습니다. 둘 다 보존합니다. */
export function withClassName<State>(
  base: string,
  custom?: string | ((state: State) => string | undefined),
) {
  return (state: State) =>
    [base, typeof custom === "function" ? custom(state) : custom]
      .filter(Boolean)
      .join(" ");
}
export function cx(...classes: (string | undefined | false)[]) {
  return classes.filter(Boolean).join(" ");
}

