/* Slider: 공통 구조는 theme.css, 컴포넌트 전용 조정은 아래에 작성합니다. */
.rbx-slider {
  display: grid;
  gap: 8px;
  width: 100%;
}
.rbx-slider-control {
  display: flex;
  align-items: center;
  height: 28px;
  touch-action: none;
}
.rbx-slider-track {
  position: relative;
  height: 6px;
  border-radius: 99px;
  background: var(--rbx-color-shift-300);
  width: 100%;
}
.rbx-slider-indicator {
  position: absolute;
  border-radius: inherit;
  background: var(--rbx-color-system-emphasis);
}
.rbx-slider-thumb {
  width: 20px;
  height: 20px;
  border: 3px solid var(--rbx-color-system-emphasis);
  border-radius: 50%;
  background: var(--rbx-color-extended-white-100);
}
.rbx-slider[data-orientation="vertical"] .rbx-slider-control {
  width: 28px;
  height: 180px;
  justify-content: center;
}
.rbx-slider[data-orientation="vertical"] .rbx-slider-track {
  width: 6px;
  height: 100%;
}

"use client";

import type { ComponentProps } from "react";
import { Slider as Primitive } from "@base-ui/react/slider";
import { withClassName } from "../../lib/cx";
import "./slider.css";

// 동작과 접근성은 Base UI가 담당합니다. 이 파일은 스타일 연결만 담당합니다.
function SliderRoot({
  className,
  ...props
}: ComponentProps<typeof Primitive.Root>) {
  return (
    <Primitive.Root
      {...props}
      className={withClassName("rbx-slider", className)}
    />
  );
}

function SliderLabel({
  className,
  ...props
}: ComponentProps<typeof Primitive.Label>) {
  return (
    <Primitive.Label
      {...props}
      className={withClassName("rbx-label", className)}
    />
  );
}

function SliderValue({
  className,
  ...props
}: ComponentProps<typeof Primitive.Value>) {
  return (
    <Primitive.Value
      {...props}
      className={withClassName("rbx-description", className)}
    />
  );
}

function SliderControl({
  className,
  ...props
}: ComponentProps<typeof Primitive.Control>) {
  return (
    <Primitive.Control
      {...props}
      className={withClassName("rbx-slider-control", className)}
    />
  );
}

function SliderTrack({
  className,
  ...props
}: ComponentProps<typeof Primitive.Track>) {
  return (
    <Primitive.Track
      {...props}
      className={withClassName("rbx-slider-track", className)}
    />
  );
}

function SliderIndicator({
  className,
  ...props
}: ComponentProps<typeof Primitive.Indicator>) {
  return (
    <Primitive.Indicator
      {...props}
      className={withClassName("rbx-slider-indicator", className)}
    />
  );
}

function SliderThumb({
  className,
  ...props
}: ComponentProps<typeof Primitive.Thumb>) {
  return (
    <Primitive.Thumb
      {...props}
      className={withClassName("rbx-slider-thumb", className)}
    />
  );
}

// Root/Portal 등 스타일 없는 파트와 제네릭 API는 원본을 그대로 보존합니다.
export const Slider = {
  ...Primitive,
  Root: SliderRoot,
  Label: SliderLabel,
  Value: SliderValue,
  Control: SliderControl,
  Track: SliderTrack,
  Indicator: SliderIndicator,
  Thumb: SliderThumb,
};

/** Base UI는 className에 문자열 또는 상태 함수를 받습니다. 둘 다 보존합니다. */
export function withClassName<State>(
  base: string,
  custom?: string | ((state: State) => string | undefined),
) {
  return (state: State) =>
    [base, typeof custom === "function" ? custom(state) : custom]
      .filter(Boolean)
      .join(" ");
}
export function cx(...classes: (string | undefined | false)[]) {
  return classes.filter(Boolean).join(" ");
}

