}
.rbx-tab {
  padding: 14px 0;
  border: 0;
  border-bottom: 2px solid transparent;
  background: transparent;
  color: var(--rbx-color-content-muted);
  font: 600 1rem var(--rbx-font-body);
  cursor: pointer;
  white-space: nowrap;
}
.rbx-tab[data-active] {
  color: var(--rbx-color-content-emphasis);
  border-bottom-color: var(--rbx-color-content-emphasis);
}
.rbx-tab-panel {
