/* Toast: 공통 구조는 theme.css, 컴포넌트 전용 조정은 아래에 작성합니다. */
.rbx-toast-viewport {
  position: fixed;
  z-index: var(--rbx-layer-toast);
  right: 20px;
  bottom: 20px;
  width: min(360px, calc(100vw - 32px));
  display: flex;
  flex-direction: column;
  gap: 10px;
}
.rbx-toast {
  position: relative;
  padding: 14px;
  border: 1px solid var(--rbx-color-stroke-emphasis);
  border-radius: 12px;
  background: var(--rbx-color-surface-200);
  color: var(--rbx-color-content-emphasis);
  box-shadow: 0 8px 32px var(--rbx-color-common-shadow);
  gap: 4px;
  display: flex;
  flex-direction: column;
}
.rbx-toast-title {
  font-weight: 700;
  margin-bottom: 4px;
}
.rbx-toast .rbx-icon-button {
  position: absolute;
  top: 3px;
  right: 3px;
  background: transparent;
}

"use client";

import type { ComponentProps } from "react";
import { Toast as Primitive } from "@base-ui/react/toast";
import { withClassName } from "../../lib/cx";
import "./toast.css";

// 동작과 접근성은 Base UI가 담당합니다. 이 파일은 스타일 연결만 담당합니다.
function ToastViewport({
  className,
  ...props
}: ComponentProps<typeof Primitive.Viewport>) {
  return (
    <Primitive.Viewport
      {...props}
      className={withClassName("rbx-toast-viewport", className)}
    />
  );
}

function ToastRoot({
  className,
  ...props
}: ComponentProps<typeof Primitive.Root>) {
  return (
    <Primitive.Root
      {...props}
      className={withClassName("rbx-toast", className)}
    />
  );
}

function ToastTitle({
  className,
  ...props
}: ComponentProps<typeof Primitive.Title>) {
  return (
    <Primitive.Title
      {...props}
      className={withClassName("rbx-toast-title", className)}
    />
  );
}

function ToastDescription({
  className,
  ...props
}: ComponentProps<typeof Primitive.Description>) {
  return (
    <Primitive.Description
      {...props}
      className={withClassName("rbx-description", className)}
    />
  );
}

function ToastClose({
  className,
  ...props
}: ComponentProps<typeof Primitive.Close>) {
  return (
    <Primitive.Close
      {...props}
      className={withClassName("rbx-icon-button", className)}
    />
  );
}

function ToastAction({
  className,
  ...props
}: ComponentProps<typeof Primitive.Action>) {
  return (
    <Primitive.Action
      {...props}
      className={withClassName("rbx-button", className)}
    />
  );
}

// Root/Portal 등 스타일 없는 파트와 제네릭 API는 원본을 그대로 보존합니다.
export const Toast = {
  ...Primitive,
  Viewport: ToastViewport,
  Root: ToastRoot,
  Title: ToastTitle,
  Description: ToastDescription,
  Close: ToastClose,
  Action: ToastAction,
};

/** Base UI는 className에 문자열 또는 상태 함수를 받습니다. 둘 다 보존합니다. */
export function withClassName<State>(
  base: string,
  custom?: string | ((state: State) => string | undefined),
) {
  return (state: State) =>
    [base, typeof custom === "function" ? custom(state) : custom]
      .filter(Boolean)
      .join(" ");
}
export function cx(...classes: (string | undefined | false)[]) {
  return classes.filter(Boolean).join(" ");
}

