/* Robux FAQ: Foundation tokens + page-specific composition. No height animation in observed source. */
.rbx-accordion {
  width: 100%;
  display: flex;
  flex-direction: column;
  gap: 12px;
}
.rbx-accordion-item {
  border: 1px solid var(--rbx-color-stroke-default);
  border-radius: 8px;
  overflow: hidden;
  padding: 8px 12px;
}
.rbx-accordion-header {
  margin: 0;
}
.rbx-accordion-trigger {
  width: 100%;
  min-height: 40px;
  padding: 0;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  border: 0;
  background: transparent;
  color: var(--rbx-color-content-default);
  font: var(--rbx-typography-title-medium-font);
  text-align: left;
  cursor: pointer;
}
.rbx-accordion-panel {
  color: var(--rbx-color-content-default);
  overflow: hidden;
  font: var(--rbx-typography-body-medium-font);
  white-space: pre-wrap;
  padding-bottom: 12px;
}
.rbx-accordion-chevron {
