/* Roblox Home / Navigation.css: 40px row, 40px icon slot, 24px glyph. */
.rbx-navigation-item {
  box-sizing: border-box;
  position: relative;
  isolation: isolate;
  display: flex;
  align-items: center;
  gap: 8px;
  width: 100%;
  min-width: 0;
